// 무거운 인터랙티브 데모는 뷰포트에 들어올 때 코드 스플릿 청크를 받아 마운트한다.
const DashboardEditDemo = lazy(() =>
  import("./components/demos/DashboardEditDemo").then((module) => ({ default: module.DashboardEditDemo })),
);

function LazyInView({ children, minHeight = 540 }: { children: ReactNode; minHeight?: number }): ReactElement {
  const ref = useRef<HTMLDivElement | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (visible) return;
    const element = ref.current;
    if (!element) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "300px" },
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [visible]);

  return (
    <div ref={ref} style={visible ? undefined : { minHeight }}>
      {visible ? (
        <Suspense fallback={<p className="demo-loading">데모를 불러오는 중…</p>}>{children}</Suspense>
      ) : null}
    </div>
  );
}

