import type { ReactElement } from "react";
import { ExternalLink } from "lucide-react";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData } from "../data";

export function LinksSection(): ReactElement {
  return (
    <section className="section" id="links">
      <SectionHeader index="06" eyebrow="Links" />
      <div className="link-card-list">
        {portfolioData.links.map((link) => (
          <a className="link-card" href={link.href} target="_blank" rel="noreferrer" key={link.href}>
            <div>
              <h3>{link.label}</h3>
              {link.description && <p>{link.description}</p>}
            </div>
            <ExternalLink size={18} aria-hidden="true" />
          </a>
        ))}
      </div>
    </section>
  );
}
