import type { ReactElement } from "react";
import { SectionHeader } from "../components/SectionHeader";
import { SubDetailBlock } from "../components/SubDetailBlock";
import { portfolioData } from "../data";
import { demoBySubDetailId, imageBySubDetailId } from "../projectDetailContent";
import type { ProjectGroup } from "../types";

export function ProjectDetailSection(): ReactElement {
  return (
    <section className="section" id="project-detail">
      <SectionHeader index="04" eyebrow="Project Detail"/>
      <div className="project-detail-group-list">
        {portfolioData.projectGroups.map((group) => (
          <ProjectDetailGroup group={group} key={group.id} />
        ))}
      </div>
    </section>
  );
}

function ProjectDetailGroup({ group }: { group: ProjectGroup }): ReactElement {
  return (
    <article className="project-detail-group" id={`detail-${group.id}`}>
      <header className="project-detail-group-header">
        <span className="project-detail-group-number">{group.number}</span>
        <div>
          <h3>{group.title}</h3>
          <p>{group.text}</p>
        </div>
      </header>
      <div className="library-detail-stack">
        {group.subDetails.map((subDetail) => (
          <SubDetailBlock
            key={subDetail.id}
            subDetail={subDetail}
            demo={demoBySubDetailId[subDetail.id]}
            image={imageBySubDetailId[subDetail.id]}
          />
        ))}
      </div>
    </article>
  );
}
