import type { ReactElement, ReactNode } from "react";
import { ExternalLink } from "lucide-react";
import type { ProjectSubDetail } from "../types";

export function SubDetailBlock({
  subDetail,
  demo,
  image,
}: {
  subDetail: ProjectSubDetail;
  demo?: ReactNode;
  image?: { src: string; alt: string };
}): ReactElement {
  const titleId = `${subDetail.id}-title`;

  return (
    <section className="library-detail-section" id={subDetail.id} aria-labelledby={titleId}>
      <div className="library-detail-label">
        <span>{subDetail.number}</span>
        <small>{subDetail.title}</small>
      </div>
      <div className="library-detail-content">
        <h3 id={titleId}>{subDetail.title}</h3>
        {image && <img className="sub-detail-image" src={image.src} alt={image.alt} />}
        {demo && <div className="library-detail-demo">{demo}</div>}
        <div className="library-detail-point">
          <strong>문제</strong>
          <p>{subDetail.problem}</p>
        </div>
        <div className="library-detail-point">
          <strong>목표</strong>
          <p>{subDetail.goal}</p>
        </div>
        <div className="library-detail-point">
          <strong>역할</strong>
          <p>{subDetail.role}</p>
        </div>
        <div className="library-detail-point">
          <strong>실행</strong>
          <ul className="library-detail-list">
            {subDetail.execution.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ul>
        </div>
        <div className="library-detail-point">
          <strong>결과</strong>
          <p>{subDetail.result}</p>
        </div>
        {subDetail.blogLinks && subDetail.blogLinks.length > 0 && (
          <div className="sub-detail-blog-links">
            {subDetail.blogLinks.map((link) => (
              <a key={link.href} className="text-button" href={link.href} target="_blank" rel="noreferrer">
                {link.label} <ExternalLink size={14} aria-hidden="true" />
              </a>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}
