import type { ReactElement, ReactNode } from "react";

export function SectionHeader({
  index,
  eyebrow,
  title,
  description,
}: {
  index?: string;
  eyebrow: string;
  title?: ReactNode;
  description?: ReactNode;
}): ReactElement {
  return (
    <div className="section-header">
      <p className="eyebrow">
        {index && <span className="section-index">{index}</span>}
        {eyebrow}
      </p>
      {title && <h2>{title}</h2>}
      {description && <p>{description}</p>}
    </div>
  );
}
