import type { ReactElement } from "react";

type Editor = {
  name: string;
  text: string;
  bullets: string[];
};

const diagramHeadline = "Front ↔ Back-End 사이 Message Engine의 등록 흐름";

const editors: Editor[] = [
  {
    name: "데이터 모델 편집기 (Record)",
    text: "Record·Field 구조를 트리 그리드로 정의",
    bullets: [
      "XML 스펙 파싱으로 복합 헤더 컬럼 동적 생성 — 필드 유형 추가 시 화면 코드 수정 불필요",
      "다른 Record 참조로 하위 구조 재사용",
      "유효성 검증 결과를 에러 목록으로 즉시 노출",
    ],
  },
  {
    name: "인터페이스 편집기 (Interface)",
    text: "Request·Response Record와 연결 Service를 함께 관리",
    bullets: [
      "조건별 다중 Response를 그리드로 관리, Response마다 Record 지정",
      "화면 내 검색 모달로 참조·연결 — 화면 이동 없이 등록 연속",
    ],
  },
  {
    name: "서비스 편집기 (Service)",
    text: "정의된 Record를 Request·Response로 묶어 입출력 계약 구성",
    bullets: ["Record 검색 모달로 등록된 Record 재사용"],
  },
  {
    name: "데이터 매핑 편집기 (Mapping)",
    text: "Record 간 Source·Target 필드를 연결해 매핑 규칙 구성",
    bullets: [
      "필드 드래그 연결 + 다중 선택 일괄 연결로 클릭 수 절감",
      "권한·소유자·비즈니스 권한별 Lock으로 동시 편집 충돌 방지",
    ],
  },
];

function MedBox({ editor, wide = false }: { editor: Editor; wide?: boolean }): ReactElement {
  return (
    <div className={wide ? "med-box med-box-wide" : "med-box"}>
      <h4>{editor.name}</h4>
      <p className="med-box-role">{editor.text}</p>
      <ul>
        {editor.bullets.map((bullet) => <li key={bullet}>{bullet}</li>)}
      </ul>
    </div>
  );
}

export function MessageEngineDiagram(): ReactElement {
  const [record, iface, service, mapping] = editors;

  return (
    <figure className="message-engine-diagram" aria-label="Message Engine 영역의 편집기별 등록 흐름">
      <p className="med-headline">{diagramHeadline}</p>

      <div className="med-frame">
        <div className="med-frame-head">
          <span className="med-frame-ext">Front 시스템</span>
          <span className="med-arrow" aria-hidden="true">→</span>
          <span className="med-frame-label">Message Engine</span>
          <span className="med-arrow" aria-hidden="true">→</span>
          <span className="med-frame-ext">Back-End 시스템</span>
        </div>

        <div className="med-grid">
          <div className="med-row-2">
            <MedBox editor={iface} />
            <MedBox editor={service} />
          </div>

          <div className="med-merge" aria-hidden="true">
            <span className="med-merge-label">Request·Response Record 지정</span>
            <span className="med-merge-arrow">▼</span>
          </div>

          <MedBox editor={record} wide />

          <div className="med-merge med-merge-single" aria-hidden="true">
            <span className="med-merge-label">Source·Target Record 연결</span>
            <span className="med-merge-arrow">▼</span>
          </div>

          <MedBox editor={mapping} wide />
        </div>
      </div>

      <figcaption>
        iGate 프레임워크의 <strong>Message Engine</strong> 영역. Connector·Converter와 Process Rule Engine은
        프로젝트 범위 밖입니다.
      </figcaption>
    </figure>
  );
}
